#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

vector<long long> dataList, sumList;

void computeSubsets(int index, long long currentSum) {
    if (index == (int)dataList.size()) {
        sumList.push_back(currentSum);
        return;
    }
    computeSubsets(index + 1, currentSum + dataList[index]);
    computeSubsets(index + 1, currentSum);
}

bool verifyCondition(long long M, long long W, long long x) {
    if (x == M) return true;

    long long totalX = x + M;
    while (totalX > 0) {
        if (totalX % W > 1) return false;
        totalX /= W;
    }
    return true;
}

int main() {
    string line;
    getline(cin, line);
    stringstream ss(line);
    long long W, M;
    ss >> W >> M;

    if (W == 2) {
        cout << "YES" << endl;
        return 0;
    }

    dataList.clear();
    dataList.push_back(1LL);
    dataList.push_back(W);

    long long val = W;
    const long long MAX_LIMIT = 10000000000LL; // 1e10

    while (true) {
        val *= W;
        if (val < 0 || val > MAX_LIMIT) break;
        dataList.push_back(val);
    }

    sumList.clear();
    computeSubsets(0, 0);

    bool answerFlag = false;
    for (auto candidateSum : sumList) {
        answerFlag |= verifyCondition(M, W, candidateSum);
        if (answerFlag) break;
    }

    cout << (answerFlag ? "YES" : "NO") << endl;
    return 0;
}
